                       // particles, render-only\n\nfunction newGame() {\n  const seed = mode === \"daily\" ? Sim.dailySeed(Sim.utcDay())\n                                : (Math.random() * 2 ** 32) >>> 0;\n  G = Sim.createState(seed);\n  taps = []; pendingTap = false; burst = []; shake = 0;\n}\n\n/* ---------- juice ---------- */\nfunction puff(x, y, col) {\n  for (let i = 0; i < 10; i++) {\n    const a = Math.random() * Math.PI * 2, v = 60 + Math.random() * 120;\n    burst.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 0.5, col });\n  }\n}\nfunction handleEvents() {\n  for (const ev of G.events) {\n    if (ev.t === \"latch\")      { shake = 4;  puff(G.x, G.y, \"#16d3ff\"); }\n    else if (ev.t === \"spark\") { puff(ev.x, ev.y, \"#ffd24a\"); }\n    else if (ev.t === \"die\")   { shake = 10; }\n  }\n}\n\n/* ---------- render ---------- */\nfunction draw() {\n  const camX = VIEW_W / 2, camYpix = viewH * 0.62;\n  const shx = (Math.random() - .5) * shake, shy = (Math.random() - .5) * shake;\n  shake *= 0.85;\n\n  const grd = ctx.createLinearGradient(0, 0, 0, viewH);\n  grd.addColorStop(0, \"#0b0c22\"); grd.addColorStop(1, \"#06060f\");\n  ctx.fillStyle = grd; ctx.fillRect(0, 0, VIEW_W, viewH);\n\n  ctx.save();\n  ctx.translate(camX + shx, camYpix - G.camY + shy);\n\n  const A = G.track.anchors, top = G.camY - viewH, bot = G.camY + viewH;\n  for (const s of G.track.sparks) {\n    if (s.hit || s.y < top || s.y > bot) continue;\n    ctx.fillStyle = \"#ffd24a\"; ctx.shadowColor = \"#ffd24a\"; ctx.shadowBlur = 14;\n    ctx.beginPath(); ctx.arc(s.x, s.y, 4.5, 0, 7); ctx.fill();\n  }\n  ctx.shadowBlur = 0;\n  for (const a of A) {\n    if (a.y < top || a.y > bot) continue;\n    ctx.strokeStyle = \"#2b3f77\"; ctx.lineWidth = 2.5;\n    ctx.beginPath(); ctx.arc(a.x, a.y, a.r, 0, 7); ctx.stroke();\n    ctx.fillStyle = \"#2b3f77\";\n    ctx.beginPath(); ctx.arc(a.x, a.y, 4, 0, 7); ctx.fill();\n    if (a.spike >= 0) {\n      const sx = a.x + Math.cos(a.spike) * a.r, sy